<?php require __DIR__.'/config.php'; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EARN Admin</title><script src="https://cdn.tailwindcss.com"></script><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><style>body{font-family:Inter,system-ui;background:#f4f6f8}.brand{background:#f28c18}.line{border:1px solid #ddd;border-radius:8px;padding:10px;width:100%}.card{background:white;border-radius:14px;padding:20px;box-shadow:0 3px 15px #00000008}</style></head><body><header class="bg-slate-950 text-white p-4"><div class="max-w-7xl mx-auto flex justify-between items-center"><b class="text-xl">EARN <span class="text-orange-400">ADMIN</span></b><div class="flex gap-3"><a href="index.php" class="border rounded-lg px-3 py-2">Storefront</a><button id="logout" class="brand rounded-lg px-3 py-2">Sign out</button></div></div></header><main class="max-w-7xl mx-auto p-4 space-y-5"><section id="login" class="card max-w-lg mx-auto"><h1 class="text-2xl font-black mb-3">Administrator sign in</h1><p class="text-sm text-slate-500 mb-4">Sign in with your admin account created by setup_admin.php.</p><form id="loginForm" class="space-y-3"><input name="email" type="email" required class="line" placeholder="Admin email"><input name="password" type="password" required class="line" placeholder="Password"><button class="brand text-white rounded-lg p-3 w-full font-bold">Sign in</button></form></section><div id="dashboard" class="hidden space-y-5"><h1 class="text-3xl font-black">Store dashboard</h1><div id="stats" class="grid grid-cols-2 lg:grid-cols-4 gap-4"></div><section class="card"><h2 class="font-black text-xl mb-3">Revenue — last 30 days</h2><canvas id="chart" height="100"></canvas></section><section class="card"><h2 class="font-black text-xl mb-3">Add / edit product</h2><form id="productForm" class="grid md:grid-cols-2 gap-3"><input name="id" type="hidden"><input name="title" required class="line" placeholder="Product title"><input name="category" required class="line" placeholder="Category"><input name="brand" required class="line" placeholder="Brand"><input name="price" type="number" min=".01" step=".01" required class="line" placeholder="Price (KSh)"><input name="stock" type="number" min="0" required class="line" placeholder="Stock"><input name="image_url" type="url" class="line" placeholder="Image URL (optional if uploading)"><label class="block text-sm md:col-span-2">Upload product image from computer<input id="imageFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" class="line mt-1"></label><p class="text-xs text-slate-500 md:col-span-2">JPG, PNG, WEBP or GIF · maximum 5 MB. Uploaded images are saved in uploads/products.</p><textarea name="description" class="line md:col-span-2" placeholder="Description"></textarea><button class="brand text-white rounded-lg p-3 font-bold">Save product</button><button type="reset" class="border rounded-lg p-3" onclick="this.form.elements.id.value=''">Clear</button></form></section><section class="card"><h2 class="font-black text-xl mb-3">Inventory</h2><input id="filter" class="line mb-3" placeholder="Filter products" oninput="renderProducts()"><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left bg-slate-100"><th class="p-2">Product</th><th class="p-2">Category</th><th class="p-2">Price</th><th class="p-2">Stock</th><th class="p-2">Actions</th></tr></thead><tbody id="productRows"></tbody></table></div></section><section class="card"><h2 class="font-black text-xl mb-3">Orders</h2><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left bg-slate-100"><th class="p-2">Reference / customer</th><th class="p-2">Items</th><th class="p-2">Total</th><th class="p-2">Status</th><th class="p-2">Update</th></tr></thead><tbody id="orderRows"></tbody></table></div></section></div></main><div id="toast" class="fixed bottom-5 right-5 bg-slate-950 text-white rounded-lg p-3 hidden"></div>
<script>
let csrf='',user=null,products=[],orders=[],chart=null;const money=n=>'KSh '+Number(n||0).toLocaleString('en-KE',{maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(a,d=null){let o={method:d?'POST':'GET',headers:{}};if(d){o.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};o.body=JSON.stringify(d)}let r=await fetch('api.php?action='+a,o),j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Request failed');return j}
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),3000)}
async function boot(){try{let m=await api('me');csrf=m.csrf;user=m.user;if(user?.role==='admin')showDash()}catch(e){}}
async function signIn(e){e.preventDefault();let f=new FormData(e.target);try{let r=await api('login',{email:f.get('email'),password:f.get('password')});user=r.user;csrf=r.csrf;if(user.role!=='admin')throw Error('This account is not an administrator.');showDash()}catch(e){toast(e.message)}}
function showDash(){document.getElementById('login').classList.add('hidden');document.getElementById('dashboard').classList.remove('hidden');refresh()}
async function refresh(){try{let [s,p,o]=await Promise.all([api('admin_stats'),api('admin_products'),api('admin_orders')]);products=p.filter(x=>+x.active===1);orders=o;document.getElementById('stats').innerHTML=[['Active products',s.products],['Orders',s.orders],['Pending',s.pending],['Confirmed revenue',money(s.revenue)]].map(([a,b])=>`<div class="card"><p class="text-slate-500">${a}</p><b class="text-2xl">${b}</b></div>`).join('');if(chart)chart.destroy();chart=new Chart(document.getElementById('chart'),{type:'line',data:{labels:s.daily.map(x=>x.day),datasets:[{label:'Revenue (KSh)',data:s.daily.map(x=>+x.revenue),tension:.25}]},options:{responsive:true}});renderProducts();renderOrders()}catch(e){toast(e.message)}}
function renderProducts(){let q=(document.getElementById('filter')?.value||'').toLowerCase();document.getElementById('productRows').innerHTML=products.filter(p=>(p.title+' '+p.brand+' '+p.category).toLowerCase().includes(q)).map(p=>`<tr class="border-b"><td class="p-2">${esc(p.title)}<div class="text-xs text-slate-500">${esc(p.brand)}</div></td><td class="p-2">${esc(p.category)}</td><td class="p-2">${money(p.price)}</td><td class="p-2">${p.stock}</td><td class="p-2 whitespace-nowrap"><button class="text-blue-700 mr-2" onclick="edit(${p.id})">Edit</button><button class="text-red-600" onclick="del(${p.id})">Remove</button></td></tr>`).join('')}
function edit(id){let p=products.find(x=>+x.id===id),f=document.getElementById('productForm');for(let k of ['id','title','category','brand','price','stock','image_url','description'])f.elements[k].value=p[k]??'';f.scrollIntoView({behavior:'smooth'})}
async function del(id){if(!confirm('Remove this product from the storefront?'))return;try{await api('delete_product',{id});toast('Product removed');refresh()}catch(e){toast(e.message)}}
function renderOrders(){document.getElementById('orderRows').innerHTML=orders.map(o=>`<tr class="border-b align-top cursor-pointer hover:bg-orange-50" onclick="if(!event.target.closest('select'))location.href='admin_order.php?id=${o.id}'"><td class="p-2"><a class="text-blue-700 underline font-bold" href="admin_order.php?id=${o.id}">${esc(o.order_code)}</a><br>${esc(o.customer_name)}<br><small>${esc(o.email)} · ${esc(o.phone)}<br>${esc(o.address)}</small></td><td class="p-2">${esc(o.items||'')}</td><td class="p-2">${money(o.total)}</td><td class="p-2">${esc(o.status)}</td><td class="p-2"><select class="line" onchange="status(${o.id},this.value)">${['Pending','Confirmed','Shipped','Delivered','Cancelled'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td class="p-3" colspan="5">No orders yet.</td></tr>'}
async function status(id,status){try{await api('update_order',{id,status});toast('Order updated');refresh()}catch(e){toast(e.message)}}
document.getElementById('loginForm').onsubmit=signIn;document.getElementById('productForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),d={};for(let k of ['id','title','category','brand','price','stock','image_url','description'])d[k]=f.get(k);d.id=+d.id;d.price=+d.price;d.stock=+d.stock;try{let file=document.getElementById('imageFile').files[0];if(file){let fd=new FormData();fd.append('image',file);let r=await fetch('api.php?action=upload_image',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});let j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Image upload failed');d.image_url=j.image_url;}await api('save_product',d);e.target.reset();toast('Product saved');refresh()}catch(e){toast(e.message)}};
document.getElementById('logout').onclick=async()=>{try{await api('logout',{});location.href='index.php'}catch(e){location.href='index.php'}};boot();
</script></body></html>